def find_root(p):
    for i in range(len(p)):
        if p[i] == i:
            return i
    return -1

def make_valid_sequence(n, a):
    root = find_root(a)
    if root != -1:
        return 0, a

    changes = 0
    for i in range(n):
        if a[i] != i:
            a[i] = i
            changes += 1

    return changes, a

# Read input
n = int(input())
a = list(map(int, input().split()))

# Make the sequence valid
changes, valid_sequence = make_valid_sequence(n, a)

# Output the result
print(changes)
print(' '.join(map(str, valid_sequence)))
